    document.body.append(drawerBackdrop,promptDrawer);
    const form=promptDrawer.querySelector('form'),steps=[...promptDrawer.querySelectorAll('[data-prompt-step-jump]')],panes=[...promptDrawer.querySelectorAll('[data-prompt-pane]')],back=promptDrawer.querySelector('[data-prompt-back]'),next=promptDrawer.querySelector('[data-prompt-next]'),submit=promptDrawer.querySelector('[data-prompt-submit]');let step=0,returnFocus=null;
    const populate=()=>{document.getElementById('intel-prompt-base-name').textContent=activePrompt.name;document.getElementById('intel-prompt-base-version').textContent=`${activePrompt.version} · ${activePrompt.environment}`;document.getElementById('intel-prompt-base-app').textContent=activePrompt.app;document.getElementById('intel-prompt-next-version').textContent=nextVersion(activePrompt);};
    const renderReview=()=>{const fd=new FormData(form);document.getElementById('intel-prompt-review').innerHTML=`<article><small>Candidate</small><b>${activePrompt.id}:${nextVersion(activePrompt)}</b><span>Forked from ${activePrompt.version} · ${activePrompt.environment}</span></article><article><small>Change</small><b>${fd.get('changeType')}</b><span>${fd.get('summary')}</span></article><article><small>Testing</small><b>${fd.get('suite')}</b><span>${fd.get('testEnvironment')} · ${fd.get('checks')}</span></article><article><small>Review policy</small><b>${fd.get('reviewer')}</b><span>${fd.get('gate')} · ${fd.get('rollback')}</span></article>`;};
    const showStep=index=>{step=Math.max(0,Math.min(4,index));steps.forEach((item,i)=>{item.classList.toggle('is-active',i===step);item.classList.toggle('is-complete',i<step)});panes.forEach((pane,i)=>pane.classList.toggle('is-active',i===step));back.disabled=step===0;next.hidden=step===4;submit.hidden=step!==4;if(step===4)renderReview();promptDrawer.querySelector('.intel-prompt-drawer-body')?.scrollTo({top:0,behavior:'smooth'});refreshIcons();};
